.root { --vt-surface: #ffffff; --vt-surface-2: #f9f9f9; --vt-surface-deep: #36363e; --vt-ink: #000000; --vt-ink-soft: #717275; --vt-on-deep: #ffffff; --vt-accent: #f65129; --vt-on-accent: #ffffff; --vt-accent-ink: #f65129; --vt-accent-on-deep: #ffd74f; --vt-line: #e9eaeb; background: var(--vt-surface); color: var(--vt-ink); font-family: 'Fira Sans Condensed', 'Noto Sans Display', sans-serif; line-height: 1.5; -webkit-font-smoothing: antialiased; }
.root, .root *, .root *::before, .root *::after { box-sizing: border-box; }
.root :where(a) { color: inherit; text-decoration: none; }
.root :where(h1, h2, h3, h4, h5, h6) { color: var(--vt-ink); font-weight: 600; line-height: 1.2; margin: 0; }
.root :where(p) { color: var(--vt-ink-soft); margin: 0; }
.root :where(img) { display: block; max-width: 100%; }
.root a:focus-visible { outline: 2px solid var(--vt-accent); outline-offset: 2px; border-radius: 2px; }
.nav { position: sticky; top: 0; z-index: 20; background: var(--vt-surface); border-bottom: 1px solid var(--vt-line); }
.navIn { max-width: 1200px; margin: 0 auto; min-height: 72px; padding: 0 24px; display: flex; align-items: center; justify-content: space-between; gap: 24px; }
.logo { font-size: 1.5rem; font-weight: 700; }
.navLinks { display: flex; align-items: center; gap: 2rem; }
.navLinks a { position: relative; padding: 8px 0; color: var(--vt-ink-soft); font-weight: 600; border-bottom: 2px solid transparent; transition: color 0.3s, border-bottom-color 0.3s; }
.navLinks a:hover { color: var(--vt-accent-ink); border-bottom-color: var(--vt-accent); }
.hero { position: relative; min-height: 80vh; display: flex; align-items: center; justify-content: center; overflow: hidden; background: var(--vt-surface-deep); }
.heroImage { position: absolute; inset: 0; background-position: center; background-size: cover; }
.heroOverlay { position: absolute; inset: 0; background: var(--vt-ink); opacity: 0.35; }
.heroContent { position: relative; z-index: 1; width: 100%; display: flex; justify-content: center; padding: 110px 24px; }
.heroInner { max-width: 920px; width: 100%; text-align: center; color: var(--vt-on-deep); }
.kicker { margin-bottom: 12px; color: var(--vt-accent-on-deep); font-size: 0.9rem; font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; }
.heroTitle { margin-bottom: 28px; color: var(--vt-on-deep); font-size: 3.5rem; font-weight: 700; line-height: 1.1; }
.filterBar { display: flex; align-items: center; justify-content: center; flex-wrap: wrap; gap: 14px; padding: 18px 22px; background: var(--vt-surface); border: 1px solid var(--vt-line); border-radius: 16px; }
.filterLabel { color: var(--vt-accent-ink); font-size: 0.85rem; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; }
.filterTags { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; }
.filterTag { padding: 7px 14px; border: 1px solid var(--vt-line); border-radius: 999px; background: var(--vt-surface-2); color: var(--vt-ink-soft); font-size: 0.9rem; font-weight: 600; transition: background 0.3s, border-color 0.3s, color 0.3s; }
.filterTag:hover { background: var(--vt-accent-on-deep); border-color: var(--vt-accent-on-deep); color: var(--vt-ink); }
.filterCta { padding: 10px 18px; border-radius: 999px; background: var(--vt-accent); color: var(--vt-on-accent); font-weight: 600; transition: background 0.3s, color 0.3s; }
.filterCta:hover { background: var(--vt-accent-on-deep); color: var(--vt-ink); }
.about { padding: 100px 0; background: var(--vt-surface); }
.about > .sectionInner { display: grid; grid-template-columns: 1fr 1fr; gap: 4rem; align-items: center; }
.sectionInner { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.aboutText { max-width: 540px; }
.smallTitle { margin-bottom: 10px; color: var(--vt-accent-ink); font-size: 0.9rem; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; }
.sectionTitle { margin-bottom: 20px; font-size: 2.75rem; }
.paragraph { margin-bottom: 14px; font-size: 1.05rem; }
.aboutImages { display: flex; align-items: center; justify-content: center; gap: 24px; }
.aboutImageMain { width: 340px; height: 340px; object-fit: cover; border-radius: 50%; border: 8px solid var(--vt-surface-2); }
.aboutImageSmall { width: 220px; height: 220px; object-fit: cover; border-radius: 50%; border: 8px solid var(--vt-accent-on-deep); }
.featured { position: relative; min-height: 420px; display: flex; align-items: center; overflow: hidden; }
.featuredBg { position: absolute; inset: 0; background-position: center; background-size: cover; }
.featuredOverlay { position: absolute; inset: 0; background: var(--vt-ink); opacity: 0.45; }
.featuredCard { position: relative; z-index: 1; max-width: 460px; margin-left: 10%; padding: 40px 48px; background: var(--vt-surface-2); border-top: 8px solid var(--vt-accent); border-radius: 20px; }
.featuredTitle { margin-bottom: 14px; font-size: 1.8rem; }
.featuredHours { white-space: pre-line; font-size: 1.05rem; line-height: 1.7; }
.services { padding: 100px 0; background: var(--vt-surface-2); }
.servicesGrid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; margin-top: 44px; }
.serviceCard { padding: 28px 24px; background: var(--vt-surface); border: 1px solid var(--vt-line); border-top: 4px solid var(--vt-accent); border-radius: 16px; transition: transform 0.3s, box-shadow 0.3s; }
.serviceCard:hover { transform: translateY(-4px); box-shadow: 0 12px 24px var(--vt-line); }
.serviceNum { font-size: 2.4rem; font-weight: 700; line-height: 1; color: var(--vt-accent); }
.serviceTitle { margin: 14px 0 8px; font-size: 1.3rem; }
.serviceDesc { font-size: 0.95rem; }
.portfolio { padding: 100px 0; background: var(--vt-surface); }
.portfolioGrid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 44px; }
.portfolioCard { display: flex; flex-direction: column; overflow: hidden; background: var(--vt-surface); border: 1px solid var(--vt-line); border-radius: 16px; transition: transform 0.3s, box-shadow 0.3s; }
.portfolioCard:hover { transform: translateY(-4px); box-shadow: 0 12px 24px var(--vt-line); }
.portfolioMedia { aspect-ratio: 4 / 3; overflow: hidden; }
.portfolioMedia img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s; }
.portfolioCard:hover .portfolioMedia img { transform: scale(1.04); }
.portfolioBody { padding: 18px 20px 20px; }
.portfolioTitle { margin-bottom: 4px; font-size: 1.3rem; }
.portfolioSub { color: var(--vt-accent-ink); font-size: 0.9rem; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase; }
.contact { padding: 100px 0 0; background: var(--vt-surface-2); }
.contactGrid { display: grid; grid-template-columns: 1fr 1fr; gap: 48px; margin-top: 44px; align-items: start; }
.socialLinks { display: flex; flex-wrap: wrap; gap: 12px; }
.wave { display: block; width: 100%; height: 90px; margin-top: 60px; margin-bottom: -1px; fill: var(--vt-surface-deep); }
.footer { padding: 40px 0 32px; background: var(--vt-surface-deep); color: var(--vt-on-deep); }
.footerTop { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 24px; }
.footer :where(a) { color: var(--vt-on-deep); }
.footer :where(h1, h2, h3, h4, h5, h6) { color: var(--vt-on-deep); }
.footer .socialLinks a:hover { color: var(--vt-accent-on-deep); }
.copyright { margin-top: 28px; color: var(--vt-on-deep); font-size: 0.9rem; opacity: 0.7; text-align: center; }
@media (max-width: 991px) { .hero { min-height: 70vh; } .heroTitle { font-size: 2.75rem; } .heroContent { padding: 90px 24px; } .about > .sectionInner { grid-template-columns: 1fr; gap: 48px; } .aboutImages { order: -1; } .aboutImageMain { width: 280px; height: 280px; } .aboutImageSmall { width: 180px; height: 180px; } .featuredCard { margin-left: 5%; } .servicesGrid { grid-template-columns: repeat(2, 1fr); } .portfolioGrid { grid-template-columns: repeat(2, 1fr); } .contactGrid { grid-template-columns: 1fr; gap: 32px; } }
@media (max-width: 640px) { .navIn { flex-direction: column; gap: 8px; padding: 12px 16px; } .navLinks { gap: 1rem; flex-wrap: wrap; justify-content: center; } .navLinks a { font-size: 0.85rem; } .heroTitle { font-size: 2.2rem; } .filterBar { align-items: stretch; flex-direction: column; padding: 16px; } .filterTags { justify-content: flex-start; } .filterCta { text-align: center; } .about { padding: 64px 0; } .aboutImages { flex-direction: column; gap: 16px; } .aboutImageMain { width: 240px; height: 240px; } .aboutImageSmall { width: 160px; height: 160px; } .services { padding: 64px 0; } .servicesGrid { grid-template-columns: 1fr; margin-top: 32px; } .portfolio { padding: 64px 0; } .portfolioGrid { grid-template-columns: 1fr; margin-top: 32px; } .contact { padding-top: 64px; } .featured { min-height: 360px; } .featuredCard { margin: 0 16px; padding: 28px; } .sectionTitle { font-size: 2rem; } .footerTop { flex-direction: column; text-align: center; } .wave { height: 60px; margin-top: 40px; } }
